 8	    }
 9	
10	    /**
11	     * Returns the index of {@code target} in an ascending sorted array, or
12	     * {@link #NOT_FOUND} when the target is absent.
13	     */
14	    public static int binarySearch(int[] sortedNumbers, int target) {
15	        Objects.requireNonNull(sortedNumbers, "sortedNumbers must not be null");
16	
17	        int left = 0;
18	        int right = sortedNumbers.length - 1;
19	
20	        while (left <= right) {
21	            int middle = midpoint(left, right);
22	            int comparison = Integer.compare(sortedNumbers[middle], target);
23	
24	            if (comparison == 0) {
25	                return middle;
26	            }
27	
28	            if (comparison < 0) {
29	                left = middle + 1;
30	            } else {
31	                right = middle - 1;
32	            }
33	        }
34	
35	        return NOT_FOUND;
36	    }
37	
38	    private static int midpoint(int left, int right) {
39	        return left + (right - left) / 2;
40	    }
